//! Exhaustive witness index; expected variants do not read the production map.

use crate::ambient::ApiRejectionId;
use crate::check::rejection::RejectionSite;
use crate::divergence::Divergence;

pub(super) enum WitnessEntry {
    General {
        files: &'static [&'static str],
        variant: Option<Divergence>,
        reason: &'static str,
    },
    Reachable {
        files: &'static [&'static str],
        variant: Divergence,
    },
    Unreachable {
        files: &'static [&'static str],
        variant: Divergence,
        reason: &'static str,
    },
}

impl WitnessEntry {
    pub(super) fn files(&self) -> &'static [&'static str] {
        match self {
            Self::Reachable { files, .. }
            | Self::Unreachable { files, .. }
            | Self::General { files, .. } => files,
        }
    }

    pub(super) fn key(&self) -> (&'static str, Option<Divergence>) {
        match self {
            Self::General {
                files,
                variant,
                reason,
            } => {
                if files.is_empty() {
                    assert!(!reason.is_empty(), "unreachable entry needs a guard");
                }
                (files.first().copied().unwrap_or(""), *variant)
            }
            Self::Reachable { files, variant } => (files[0], Some(*variant)),
            Self::Unreachable {
                files,
                variant,
                reason,
            } => {
                assert!(!reason.is_empty(), "unreachable entry needs a reason");
                (files[0], Some(*variant))
            }
        }
    }
}

pub(super) fn witness_key(site: RejectionSite) -> (&'static str, Option<Divergence>) {
    witness_entry(site).key()
}

